'use strict';
// Three work areas. Forms remain mounted so switching areas does not lose input.
let currentArea='new';
let loadedPrices=false;
let priceFingerprint='';
function currentPriceFingerprint(){const data=Object.fromEntries(new FormData($('#journey-form')));delete data.customerName;delete data.tripNote;return JSON.stringify(data);}
const baseOptions=[...choices];
const sectionVisibility={new:['trip','options','review','help'],offer:['review','book','help'],order:['book','help'],orderDetail:['history']};
function showArea(area){currentArea=area;const list=area==='offers'||area==='orders';document.querySelectorAll('.work-block').forEach(section=>section.hidden=!(sectionVisibility[area]||[]).includes(section.id));$('#list-panel').hidden=!list;$('.workspace-intro').hidden=list;$('.page-progress').hidden=true;document.querySelectorAll('[data-area]').forEach(b=>{b.classList.toggle('active',b.dataset.area===area||b.dataset.area==='offers'&&area==='offer'||b.dataset.area==='orders'&&['order','orderDetail'].includes(area));b.setAttribute('aria-current',b.classList.contains('active')?'page':'false');});if(list)renderLists(area);}
function renderLists(area){const offers=area==='offers';$('#list-panel').innerHTML=`<div class="list-heading"><div><span class="eyebrow">מרחב השותפים</span><h1>${offers?'ההצעות שלי':'ההזמנות שלי'}</h1><p>${offers?'פותחים הצעה, בוחרים את האפשרות שהלקוח רוצה וממשיכים להזמנה.':'כאן עוקבים אחרי הזמנות שנוצרו דרך הקבינט.'}</p></div><button class="button primary" data-area="new">＋ לתת הצעה חדשה</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>מספר</th><th>לקוח / נסיעה</th><th>מצב</th><th></th></tr></thead><tbody>${offers?`<tr><td><strong>DEMO-Q-0141</strong></td><td>${esc($('[name=customerName]').value||'הצעה נוכחית')}<br><small>${esc(tripText())}</small></td><td>${badge(loadedPrices?'מחושב מהמחירון המקומי':'טיוטה — יש לחשב מחיר')}</td><td><button class="button primary" data-open-offer>פתיחת ההצעה ←</button></td></tr>`:state.booked?`<tr><td><strong>DEMO-R-0083</strong></td><td>${esc(state.bookingCompany)} · ${esc(state.bookingData.driverName)}</td><td>${badge('ממתינה לאישור','gold')}</td><td><button class="button" data-open-order>צפייה בהזמנה ←</button></td></tr>`:'<tr><td colspan="4"><div class="empty"><h3>עדיין אין הזמנות בתצוגה זו.</h3><p>פותחים הצעה ובוחרים אחת מהאפשרויות להזמנה.</p><button class="button" data-area="offers">פתיחת ההצעות שלי</button></div></td></tr>'}</tbody></table></div></div>`;}
function configureNavigation(){$('.header nav').innerHTML='<button data-area="new" class="active">לתת הצעה</button><button data-area="offers">הצעות</button><button data-area="orders">הזמנות</button>';const list=document.createElement('section');list.id='list-panel';list.hidden=true;$('#main').prepend(list);showArea('new');}
document.addEventListener('click',event=>{const area=event.target.closest('[data-area]');if(area){showArea(area.dataset.area);return;}if(event.target.closest('[data-open-offer]')){showArea('offer');scrollToSection('review');}if(event.target.closest('[data-open-order]'))showArea('orderDetail');const pick=event.target.closest('[data-order-choice]');if(pick){showArea('order');scrollToSection('book');}if(event.target.closest('#send-order')){if(state.booked){showArea('orderDetail');scrollToSection('history');}}});
// Explicit, accessible month picker. No invisible input has to receive the click.
let calendarSide='pickup',calendarYear=2026,calendarMonth=11;
const monthNames=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'];
function openCalendar(side){calendarSide=side;const iso=isoDate($('[name='+side+'Date]').value);const d=iso?new Date(iso+'T12:00:00'):new Date();calendarYear=d.getFullYear();calendarMonth=d.getMonth();drawCalendar();const dialog=$('#dialog');if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');}
function drawCalendar(){const selected=isoDate($('[name='+calendarSide+'Date]').value);const days=new Date(calendarYear,calendarMonth+1,0).getDate();const offset=new Date(calendarYear,calendarMonth,1).getDay();const minimum=calendarSide==='return'?isoDate($('[name=pickupDate]').value):'';$('#dialog-content').innerHTML=`<h2 id="calendar-title">${calendarSide==='pickup'?'תאריך קבלה':'תאריך החזרה'}</h2><div class="calendar-heading"><button type="button" data-month="-1" aria-label="חודש קודם">‹</button><strong aria-live="polite">${monthNames[calendarMonth]} ${calendarYear}</strong><button type="button" data-month="1" aria-label="חודש הבא">›</button></div><div class="calendar-week">${['א׳','ב׳','ג׳','ד׳','ה׳','ו׳','ש׳'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1;const value=calendarYear+'-'+String(calendarMonth+1).padStart(2,'0')+'-'+String(day).padStart(2,'0');return `<button type="button" data-calendar-value="${value}" ${minimum&&value<minimum?'disabled':''} ${selected===value?'aria-current="date"':''} aria-label="${dayString(value)}">${day}</button>`;}).join('')}</div><p class="small muted calendar-tip">בחרו יום. התאריך יירשם בפורמט יום.חודש.שנה.</p>`;$('#dialog').setAttribute('aria-labelledby','calendar-title');}
function addCalendarButtons(){for(const side of ['pickup','return']){const input=$('[data-date='+side+']');input.hidden=true;input.tabIndex=-1;input.setAttribute('aria-hidden','true');const btn=document.createElement('button');btn.type='button';btn.className='open-calendar';btn.dataset.calendar=side;btn.setAttribute('aria-label','פתיחת לוח שנה — '+(side==='pickup'?'תאריך קבלה':'תאריך החזרה'));btn.innerHTML='▦';input.parentElement.append(btn);}}
document.addEventListener('click',event=>{const e=event.target.closest('[data-calendar],[data-month],[data-calendar-value]');if(!e)return;if(e.dataset.calendar)openCalendar(e.dataset.calendar);if(e.dataset.month){const d=new Date(calendarYear,calendarMonth+Number(e.dataset.month),1);calendarYear=d.getFullYear();calendarMonth=d.getMonth();drawCalendar();}if(e.dataset.calendarValue){const input=$('[data-date='+calendarSide+']');input.value=e.dataset.calendarValue;input.dispatchEvent(new Event('change',{bubbles:true}));$('#order-review').hidden=true;if(typeof $('#dialog').close==='function')$('#dialog').close();else $('#dialog').removeAttribute('open');document.querySelector('[data-calendar='+calendarSide+']').focus();}});
function money(value,currency){return new Intl.NumberFormat('he-IL',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(value))+' '+currency;}
function renderPricedGroups(){const rows=choices;$('#vehicle-categories').innerHTML=categories.map((name,i)=>{const options=rows.filter(o=>o.categoryNames.includes(name));return `<details class="category" ${i===10?'open':''}><summary>${name}<span>${options.length} אפשרויות ＋</span></summary>${options.length?`<div class="table-wrap"><table><thead><tr><th>בחירה</th><th>חברה וקבוצה</th><th>דגמים מייצגים</th><th>מחיר לכל התקופה</th><th>פיקדון</th></tr></thead><tbody>${options.map(o=>`<tr><td><input type="checkbox" data-choice="${esc(o.id)}" data-category="${i}" aria-label="בחירת ${esc(o.company+' '+o.group)}"><span class="chosen-elsewhere" hidden>כבר נבחר</span></td><td><strong>${esc(o.company)}</strong>${esc(o.group)}</td><td>${esc(o.models)}</td><td><strong>${money(o.total,o.currency)}</strong></td><td>${money(o.deposit,o.depositCurrency)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="category-note muted">לא נמצא מחיר מלא למסלול ולתאריכים האלו. אפשר לפנות לעידן לבדיקה.</p>'}</details>`;}).join('');syncChoices();updateOfferPrices();}
function updateOfferPrices(){document.querySelectorAll('[data-order-choice]').forEach(btn=>{const o=choices.find(o=>o.id===btn.dataset.orderChoice);if(!o?.total)return;const article=btn.closest('.inline-option');article.querySelector('.inline-option-action b').textContent=money(o.total,o.currency);article.querySelector('.inline-option-action small').textContent='פיקדון '+money(o.deposit,o.depositCurrency)+' · לפי המחירון המקומי';});}
async function loadPrices(scroll=true){const button=$('#journey-form button.primary');const note=$('.design-price-note');button.disabled=true;button.textContent='מחשב מחירים…';note.textContent='מחשב באמצעות המחשבון של התוכנית…';try{const requestedFingerprint=currentPriceFingerprint();const data=Object.fromEntries(new FormData($('#journey-form')));for(const n of ['crossBorder','gps','chains','driverOk','creditOk'])data[n]=$('[name='+n+']').checked;data.seats=data.seats==='ללא'?'0':data.seats;const response=await fetch('/api/prices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'לא ניתן לחשב');if(requestedFingerprint!==currentPriceFingerprint())throw Error('הנתונים השתנו בזמן החישוב. יש לחשב שוב.');choices.splice(0,choices.length,...result.options.map(o=>({...o,categoryNames:o.categories})));state.selected.clear();state.bookingOption=null;loadedPrices=true;priceFingerprint=requestedFingerprint;renderPricedGroups();note.textContent=result.message+' · '+result.options.length+' אפשרויות עם מחיר מלא';note.classList.add('calculated');if(scroll)scrollToSection('options');}catch(error){loadedPrices=false;note.textContent='המחירים לא חושבו: '+error.message+' — אין להשתמש במחיר קודם.';note.classList.remove('calculated');choices.splice(0,choices.length);state.selected.clear();renderPricedGroups();}finally{button.disabled=false;button.textContent='חישוב והצגת המחירים למטה ↓';}}
// Capture the calculation action before the earlier design-only submit handler.
document.addEventListener('submit',event=>{if(event.target.id==='journey-form'){event.preventDefault();event.stopImmediatePropagation();if(event.target.reportValidity()&&validateTrip())loadPrices();}},true);
document.addEventListener('change',event=>{if(event.target.matches('[data-choice]'))updateOfferPrices();});
function invalidatePrices(event){if(!event.target.closest('#journey-form')||['customerName','tripNote'].includes(event.target.name)||!loadedPrices)return;loadedPrices=false;$('#order-fields').disabled=true;$('#order-review').hidden=true;$('.design-price-note').textContent='פרטי הנסיעה השתנו. לחצו שוב על חישוב המחירים — אין להזמין לפי המחיר הקודם.';$('.design-price-note').classList.remove('calculated');}
document.addEventListener('change',invalidatePrices);document.addEventListener('input',invalidatePrices);
document.addEventListener('click',event=>{if(event.target.closest('[data-order-choice],#send-order')&&(!loadedPrices||priceFingerprint!==currentPriceFingerprint())){event.preventDefault();event.stopImmediatePropagation();toast('יש לחשב מחדש לפי פרטי הנסיעה לפני הזמנה.');scrollToSection('trip');}},true);
configureNavigation();addCalendarButtons();loadPrices(false);

document.addEventListener('click',event=>{const button=event.target.closest('[data-order-choice]');if(!button)return;const option=choices.find(o=>o.id===button.dataset.orderChoice);if(option?.total){const p=document.createElement('p');p.className='chosen-price';p.textContent='מחיר לכל התקופה: '+money(option.total,option.currency)+' · פיקדון: '+money(option.deposit,option.depositCurrency);$('#selected-vehicle').append(p);}});
document.addEventListener('submit',event=>{if(event.target.id!=='order-form')return;const o=choices.find(o=>o.id===state.bookingOption);if(!o?.total)return;const line=[...$('#order-review').querySelectorAll('p')].find(p=>p.textContent.startsWith('מחיר ופיקדון:'));if(line)line.textContent='מחיר לכל התקופה: '+money(o.total,o.currency)+' · פיקדון: '+money(o.deposit,o.depositCurrency);});
